function DetailedOakTreeModel.Build(originCFrame)
    originCFrame = originCFrame or CFrame.new(0, 10, 0)
    
    local folder = Instance.new("Folder")
    folder.Name = "Detailed Oak Tree_Voxels"
    folder.Parent = DetailedOakTreeModel

    for _, v in ipairs(voxelData) do
        local part = Instance.new("Part")
        part.Size = Vector3.new(BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE)
        part.Material = Enum.Material.SmoothPlastic
        part.TopSurface = Enum.SurfaceType.Smooth
        part.BottomSurface = Enum.SurfaceType.Smooth
        part.Anchored = true
        part.CanCollide = true
        
        -- Color
        part.Color = Color3.fromHex(v.color)
        
        -- Position relative to origin
        local localPos = Vector3.new(v.x * BLOCK_SIZE, v.y * BLOCK_SIZE, v.z * BLOCK_SIZE)
        part.CFrame = originCFrame * CFrame.new(localPos)
        
        part.Parent = folder
    end

    DetailedOakTreeModel.Parent = Workspace
    return DetailedOakTreeModel
end

